{
  "implementation": "def solve(case):
    nodes_list = case.get('nodes')
    required_symbols_list = case.get('required_symbols')
    if not nodes_list or not required_symbols_list:
        raise ValueError('Missing nodes or required_symbols')
    required_symbols = set(required_symbols_list)
    nodes = {}
    children = {}
    root_id = None
    for n in nodes_list:
        if not all(k in n for k in ('id','parent','symbol','depth','removable','utility')):
            raise ValueError('Node missing required fields')
        nid = n['id']
        if nid in nodes:
            raise ValueError('Duplicate node id')
        nodes[nid] = n
        children.setdefault(nid, [])
        parent = n['parent']
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            if parent not in nodes:
                raise ValueError('Parent not found')
            children.setdefault(parent, []).append(nid)
    if root_id is None:
        raise ValueError('No root node')
    initial_syms = set(n['symbol'] for n in nodes_list)
    if not required_symbols.issubset(initial_syms):
        raise ValueError('Required symbol missing from tree')
    sorted_ids = sorted(nodes.keys(), key=lambda x: (-nodes[x]['depth'], x))
    retained = set(nodes.keys())
    removed_order = []
    for nid in sorted_ids:
        node = nodes[nid]
        if not node['removable']:
            continue
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        if any(cid in retained for cid in children.get(nid, [])):
            continue
        new_retained = retained - {nid}
        retained_syms = set()
        for rid in new_retained:
            retained_syms.add(nodes[rid]['symbol'])
        if required_symbols.issubset(retained_syms):
            retained = new_retained
            removed_order.append(nid)
    retained_ids = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"
}
